function updateUI(){if(!state)return;const p=state.player,l=LEVELS[state.level];$('eyebrow').textContent=`${state.mode==='campaign'?'CAMPAIGN':'SKIRMISH'} / ${String(state.level+1).padStart(2,'0')} · ${DIFF[state.difficulty].name} · 第 ${state.cycle+1} 周目`;$('missionTitle').textContent=l.name;$('sector').textContent=`SECTOR ${String(state.level+1).padStart(2,'0')} / ${l.sub}`;$('weather').textContent=['☀','☂','❄','≋'][state.weather]+' '+WEATHER[state.weather];$('score').textContent=String(state.score).padStart(6,'0');$('clock').textContent=`${String(Math.floor(state.time/60)).padStart(2,'0')}:${String(Math.floor(state.time%60)).padStart(2,'0')}`;$('hpText').textContent=`${Math.ceil(Math.max(0,p.hp))} / ${p.maxHp}`;$('hpBar').style.width=clamp(p.hp/p.maxHp*100,0,100)+'%';$('hpBar').style.background=p.hp/p.maxHp<.3?'#ed947f':'var(--teal)';$('shieldText').textContent=Math.ceil(p.shield);$('weapon').textContent=p.boost>0?'速射 · '+p.boost.toFixed(0)+'s':'穿甲炮 +'+state.upgrades.damage;$('dashStatus').textContent=p.dash>0?p.dash.toFixed(1)+'s':'就绪';$('vehicleName').textContent=state.hull==='ghost'?'幽灵 SPECTRE':state.hull==='bulwark'?'壁垒 MK.II':'游隼 MK.I';
let progress=state.killed,total=state.total,label='清剿进度',obj='消灭所有敌方单位',sub=`敌军余量 ${Math.max(0,state.total-state.spawned)+state.enemies.length} · 当前接敌 ${state.enemies.length}`;
if(state.mission==='defense'){obj='守住指挥基地';label='防守进度';sub=`第 ${Math.min(Math.ceil(state.spawned/4)||1,Math.ceil(total/4))} / ${Math.ceil(total/4)} 波 · 全部清剿后胜利`;}
if(state.mission==='resource'){obj='抢先夺取能源晶体';label='资源收集';progress=state.resources;total=state.resourceGoal;sub=`敌军 ${state.enemyResources} / ${total} · 剩余 ${Math.max(0,Math.ceil(state.limit-state.time))} 秒`;}
if(state.mission==='boss'){obj='摧毁铁幕攻城核心';label='核心破坏';const b=state.enemies.find(e=>e.type==='boss');progress=b?Math.round((1-b.hp/b.maxHp)*100):state.bossDead?100:0;total=100;sub='三阶段战斗 · 躲避扇形弹幕和炮击';}
$('objective').textContent=obj;$('progressLabel').textContent=label;$('progressText').textContent=`${progress} / ${total}`;$('progressBar').style.width=clamp(progress/total*100,0,100)+'%';$('subobjective').textContent=sub;$('baseInfo').innerHTML=state.mission==='defense'?`<div class="labelrow" style="margin-top:12px"><span>基地装甲</span><b>${Math.max(0,Math.ceil(state.base.hp))} / ${state.base.maxHp}</b></div>`:'';radar();const c=$('vehicle').getContext('2d');c.clearRect(0,0,280,135);tank(c,{...p,x:140,y:68,body:-.32,turret:-.65},1.65,true);$('fps').textContent=fps+' FPS';}
function frame(now){const real=Math.min((now-last)/1000,.1);last=now;frames++;fpsTime+=real;if(fpsTime>=1){fps=Math.round(frames/fpsTime);frames=0;fpsTime=0;}if(phase==='playing'){acc+=real;let n=0;while(acc>=1/60&&n++<6){update(1/60);acc-=1/60;if(phase!=='playing'){acc=0;break;}}for(const p of particles){p.life-=real;p.x+=p.vx*real;p.y+=p.vy*real;p.vx*=.98;p.vy*=.98;}particles=particles.filter(p=>p.life>0);for(const m of marks)m.life-=real;marks=marks.filter(m=>m.life>0);shake=Math.max(0,shake-real*15);}else acc=0;toastTimer-=real;if(toastTimer<=0)$('toast').style.opacity=0;draw();if(now-lastUI>100){updateUI();lastUI=now;}requestAnimationFrame(frame);}
