if(new URLSearchParams(location.search).has('test'))window.FrontlineTest={startRun,update,shoot,spawnEnemy,damageEnemy,damagePlayer,saveGame,loadGame,validateSave,segmentRect,segmentCircle,blocked,pathTo,finish,setupLevel,draw,updateUI,mainMenu,pause,resume,dash,get state(){return state;},get phase(){return phase;},get profile(){return profile;},get constants(){return{LEVELS,TYPES,DIFF};}};
startRun('campaign','normal','falcon',0); // Static attract battlefield, not a running demo.
